public static int nullSafeHashCode(long[] array) {
    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (long element : array) {
        int value = (int) (element ^ (element >>> 32));
        hash = 31 * hash + value;
    }
    return hash;
}

