 ParameterizedType parameterizedType = (ParameterizedType) genericType;
 Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

 Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
 for (int i = 0; i < actualTypeArguments.length; i++) {
 Type actualTypeArgument = actualTypeArguments[i];
 if (actualTypeArgument instanceof Class<?>) {
 resolvedArguments[i] = (Class<?>) actualTypeArgument;
 } else if (actualTypeArgument instanceof ParameterizedType) {
 resolvedArguments[i] = resolveArguments(actualTypeArgument, targetType);
 } else if (actualTypeArgument instanceof WildcardType) {
 WildcardType wildcardType = (WildcardType) actualTypeArgument;
 Type[] upperBounds = wildcardType.getUpperBounds();
 if (upperBounds.length == 1 && upperBounds[0] instanceof Class<?>) {
 resolvedArguments[i] = (Class<?>) upperBounds[0];
 } else {
 return null;
 }
 } else {
 return null;
 }
 }

 return resolvedArguments;
}

