public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract the year, month, and day from the time bucket
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the new day based on the dayStep
    day = (day + dayStep - 1) / dayStep * dayStep;

    // Ensure the day does not exceed the number of days in the month
    if (day > getDaysInMonth(month, year)) {
        day = getDaysInMonth(month, year);
    }

    // Reconstruct the time bucket with the new day
    return year * 10000 + month * 100 + day;
}

private static int getDaysInMonth(int month, int year) {
    switch (month) {
        case 1, 3, 5, 7, 8, 10, 12: return 31;
        case 4, 6, 9, 11: return 30;
        case 2: return isLeapYear(year) ? 29 : 28;
        default: throw new IllegalArgumentException("Invalid month: " + month);
    }
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}

int computeUTF8Size(String str, int index, int len) {
    int size = 0;
    for (int i = 0; i < len; i++) {
        char ch = str.charAt(index + i);
        if ((ch & 0x80) == 0) {
            size += 1;
        } else if ((ch & 0xE0) == 0xC0) {
            size += 2;
        } else if ((ch & 0xF0) == 0xE0) {
            size += 3;
        } else if ((ch & 0xF8) == 0xF0) {
            size += 4;
        } else if ((ch & 0xFC) == 0xF8) {
            size += 5;
        } else if ((ch & 0xFE) == 0xFA) {
            size += 6;
        } else {
            // Invalid UTF-8 character, treat as 1 byte
            size += 1;
        }
    }
    return size;
}

