public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    boolean inLiteral = false;

    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);

        if (ch == '\\' && !inLiteral) {
            inLiteral = true;
        } else if (ch == '\\' && inLiteral) {
            char nextCh = str.charAt(i + 1);
            switch (nextCh) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(nextCh);
                    break;
            }
            inLiteral = false;
            i++;
        } else {
            sb.append(ch);
        }
    }

    return sb.toString();
}

