        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // Get the offset of the CONSTANT_Utf8 entry
    int offset = classFileBuffer[constantPoolEntryIndex] & 0xFF;
    offset = (offset << 8) | (classFileBuffer[constantPoolEntryIndex + 1] & 0xFF);

    // Read the length of the UTF-8 string
    int length = classFileBuffer[offset] & 0xFF;
    offset += 2;

    // Read the UTF-8 bytes into the charBuffer
    for (int i = 0; i < length; i++) {
        charBuffer[i] = (char) classFileBuffer[offset++];
    }

    // Convert the charBuffer to a String
