public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
        long fileLength = raf.length();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            long startOffset = range.getStartOffset();
            long endOffset = range.getEndOffset();
            if (startOffset >= 0 && endOffset >= startOffset && endOffset <= fileLength) {
                raf.seek(startOffset);
                int snapshotsCount = raf.readInt();
                for (int i = 0; i < snapshotsCount; i++) {
                    ThreadSnapshot snapshot = new ThreadSnapshot();
                    snapshot.read(raf);
                    if (snapshot.getTimestamp() >= startOffset && snapshot.getTimestamp() <= endOffset) {
                        snapshots.add(snapshot);
                    }
                }
            }
        }
    }
    return snapshots;
}
